  const legendTranslateY = interpolate(frame, [60, 70], [50, 0], { extrapolateRight: "clamp" });
  const legendOpacity = interpolate(frame, [60, 70], [0, 1], { extrapolateRight: "clamp" });

  // Chart dimensions
  const chartWidth = width * 0.6;
